// Use a secret manager like aws-secrets-manager, HashiCorp Vault, or 1Password
const secretsManager = require('@aws-sdk/client-secrets-manager');

// Load secrets at runtime, never hardcode or commit them
const getSecret = async (secretName) => {
  const client = new secretsManager.SecretsManagerClient({});
  const response = await client.send(
    new secretsManager.GetSecretValueCommand({ SecretId: secretName })
  );
  return JSON.parse(response.SecretString);
};
```

