## Secure Code Template

See `app-secure.js` for a complete, security-hardened version of this application.

// Secure application with security best practices implemented
// This is a hardened version addressing all identified vulnerabilities

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const winston = require('winston');
const https = require('https');
const fs = require('fs');

const app = express();

// ========== LOGGING SETUP (Issue #8) ==========
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    ...(process.env.NODE_ENV !== 'production'
      ? [new winston.transports.Console({ format: winston.format.simple() })]
      : [])
  ],
});

app.use(morgan('combined', {
  stream: { write: message => logger.info(message.trim()) },
}));

// ========== SECURITY HEADERS (Issue #6) ==========
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

// ========== RATE LIMITING (Issue #3) ==========
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  store: new (require('rate-limit-redis'))({
    client: process.env.REDIS_URL ? require('redis').createClient({ url: process.env.REDIS_URL }) : null,
  }),
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many requests to this endpoint.',
  skipSuccessfulRequests: false,
});

app.use(generalLimiter);

// ========== ENVIRONMENT VALIDATION (Issue #4) ==========
const requiredEnvVars = ['JWT_SECRET'];
requiredEnvVars.forEach(varName => {
  if (!process.env[varName]) {
    throw new Error(`Missing required environment variable: ${varName}`);
  }
});

// ========== AUTHENTICATION MIDDLEWARE (Issue #1) ==========
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn('Access attempted without token', {
      ip: req.ip,
      path: req.path
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn('Invalid token attempt', {
        ip: req.ip,
        error: err.message
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ========== HEALTH ENDPOINT (Public) ==========
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString()
  });
});

// ========== LOGIN ENDPOINT (For token generation) ==========
app.post('/login', (req, res) => {
  // In production: validate credentials against database
  // This is simplified for demonstration
  const user = {
    id: 1,
    username: 'demo',
    role: 'user',
  };

  const token = jwt.sign(user, process.env.JWT_SECRET, {
    expiresIn: '1h'
  });

  res.json({ token });
});

// ========== USERS ENDPOINT (Protected) ==========
// Input validation middleware (Issue #2)
const validateUserQuery = [
  query('userId')
    .optional()
    .isInt({ min: 1 })
    .withMessage('userId must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be between 1 and 100'),
];

app.get('/users',
  strictLimiter,
  authenticateToken,
  validateUserQuery,
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn('Invalid user query', {
        ip: req.ip,
        errors: errors.array()
      });
      return res.status(400).json({ errors: errors.array() });
    }

    // Authorization check (Issue #1)
    if (req.user.role !== 'admin' && req.query.userId && req.user.id !== parseInt(req.query.userId)) {
      logger.warn('Unauthorized access attempt', {
        ip: req.ip,
        userId: req.user.id,
        requestedId: req.query.userId
      });
      return res.status(403).json({ error: 'Forbidden: Cannot view other users' });
    }

    // Return sanitized user data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  }
);

// ========== ERROR HANDLING (Issue #7) ==========
// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler (MUST be last)
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
  });

  const isDevelopment = process.env.NODE_ENV !== 'production';
  const response = {
    error: 'Internal Server Error',
    ...(isDevelopment && { details: err.message }),
  };

  res.status(err.status || 500).json(response);
});

// ========== SERVER STARTUP (Issue #5 - HTTPS) ==========
const PORT = process.env.PORT || 3000;

// Determine if we should use HTTPS
const useHttps = process.env.HTTPS === 'true' || process.env.NODE_ENV === 'production';

let server;

if (useHttps && process.env.SSL_KEY_PATH && process.env.SSL_CERT_PATH) {
  // Production: Use provided SSL certificates
  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH),
  };
  server = https.createServer(options, app);
  console.log('🔒 Server running with HTTPS');
} else if (process.env.NODE_ENV !== 'production') {
  // Development: Optional HTTPS with self-signed certificate
  // To generate: openssl req -x509 -newkey rsa:4096 -nodes -out cert.pem -keyout key.pem -days 365
  if (fs.existsSync('key.pem') && fs.existsSync('cert.pem')) {
    const options = {
      key: fs.readFileSync('key.pem'),
      cert: fs.readFileSync('cert.pem'),
    };
    server = https.createServer(options, app);
    console.log('🔒 Server running with HTTPS (self-signed)');
  } else {
    // HTTP fallback for development
    server = require('http').createServer(app);
    console.log('⚠️  Server running with HTTP (not recommended for production)');
  }
} else {
  // Production without proper SSL setup
  logger.error('Production environment requires HTTPS configuration');
  server = require('http').createServer(app);
  console.log('⚠️  WARNING: Production server running with HTTP');
}

server.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
  console.log(`✅ Server running on port ${PORT}`);
});

module.exports = app;

