app.use((err, req, res, next) => {
  // Log error details server-side only
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method
  });

  // Don't expose implementation details to client
  const statusCode = err.statusCode || 500;
  const clientMessage = statusCode === 500 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: clientMessage,
    requestId: req.id // For debugging without exposing stack
  });
});

// 404 handler
