    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: { action: 'deny' },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));
```

---

#### **4. ⚠️ MEDIUM: Sensitive Data Exposure**
**Severity:** MEDIUM  
**OWASP:** A01:2021 – Broken Access Control, A02:2021 – Cryptographic Failures

**Issue:** The `/users` endpoint returns personally identifiable information (PII):
- Email addresses
- User names
- User IDs

Without proper authentication, anyone can enumerate all users.

**Recommended Fix:**
```javascript
// Only expose non-sensitive fields
app.get('/users', authenticateToken, (req, res) => {
  const users = [
    { id: 1, name: 'Alice' }, // Remove email
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// Or implement proper field-level access control
app.get('/users/:id', authenticateToken, (req, res) => {
  const userId = req.params.id;

  // Validate input
  if (!/^\d+$/.test(userId)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  const user = users.find(u => u.id === parseInt(userId));
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Only return email if authenticated user is requesting their own data
  if (req.user.id !== parseInt(userId)) {
    delete user.email; // Redact email for other users
  }

  res.json(user);
});
```

---

#### **5. ⚠️ MEDIUM: No Input Validation (Parameter Injection)**
**Severity:** MEDIUM  
**OWASP:** A03:2021 – Injection

**Issue:** The endpoint doesn't validate or sanitize any inputs. While this app doesn't have parameters, adding one would expose it to injection attacks.

**Recommended Fix:**
```javascript
// Install: npm install express-validator
const { query, validationResult } = require('express-validator');

app.get('/users', 
  authenticateToken,
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('offset').optional().isInt({ min: 0 }),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = Math.min(req.query.limit || 10, 100);
    const offset = req.query.offset || 0;

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].slice(offset, offset + limit));
  }
);
```

---

#### **6. ⚠️ MEDIUM: No Error Handling**
**Severity:** MEDIUM  
**OWASP:** A05:2021 – Security Misconfiguration

**Issue:** No error handling middleware; unhandled errors will expose stack traces.

**Recommended Fix:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

#### **7. ⚠️ MEDIUM: No HTTPS Enforcement**
**Severity:** MEDIUM  
**OWASP:** A02:2021 – Cryptographic Failures

**Issue:** App listens on HTTP only; credentials can be intercepted.

**Recommended Fix:**
```javascript
// Force HTTPS in production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && 
      req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.header('host')}${req.url}`);
  }
  next();
});
```

---

### **Complete Hardened Example:**

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// Validate required environment variables
const requiredEnvVars = ['ANTHROPIC_API_KEY'];
for (const envVar of requiredEnvVars) {
  if (!process.env[envVar]) {
    throw new Error(`Missing required environment variable: ${envVar}`);
  }
}

// Security middleware
